INSERT INTO "Question" ("id", "sourceId", "questionEn", "questionFr", "answersEn", "answersFr", "correctIndex", "category", "difficulty", "createdAt") VALUES
    (gen_random_uuid()::text, 'gen-f8053bda0b294810', 'What were the medieval poets of Northern France called, counterparts to the Southern troubadours?', 'Comment appelait-on les poètes du nord de la France, équivalents des troubadours du Sud ?', '["Trouvères", "Minnesingers", "Minstrels", "Jongleurs"]'::jsonb, '["Trouvères", "Minnesingers", "Ménestrels", "Jongleurs"]'::jsonb, 0, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-071989cf7f3aed62', 'To which literary genre does the famous ''Chanson de Roland'' belong?', 'À quel genre littéraire appartient la célèbre ''Chanson de Roland'' ?', '["Chanson courtoise", "Chanson de geste", "Chanson bourguignonne", "Chanson d''aube"]'::jsonb, '["Chanson courtoise", "Chanson de geste", "Chanson bourguignonne", "Chanson d''aube"]'::jsonb, 1, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2703b00eaeca77d2', 'What is the real birth name of the singer known as Johnny Hallyday?', 'Quel est le véritable nom de naissance du chanteur Johnny Hallyday ?', '["Jean-Philippe Smet", "Jean-Philippe Hallyday", "Johnny Smet", "Jean-Philippe Clerc"]'::jsonb, '["Jean-Philippe Smet", "Jean-Philippe Hallyday", "Johnny Smet", "Jean-Philippe Clerc"]'::jsonb, 0, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-796b796f9034b7d7', 'Which musical genre did Johnny Hallyday popularize in France starting in 1960?', 'Quel genre musical Johnny Hallyday a-t-il popularisé en France à partir de 1960 ?', '["Electronic music", "Reggae", "Rock", "Jazz"]'::jsonb, '["La musique électronique", "Le reggae", "Le rock", "Le jazz"]'::jsonb, 2, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e351c9fbe18c3845', 'Johnny Hallyday was born in the city of Brussels, Belgium.', 'Johnny Hallyday est né dans la ville de Bruxelles, en Belgique.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-67b3f3c2b56daca0', 'Which American artist was a major inspiration for Johnny Hallyday when he decided to become a rocker?', 'Quel artiste américain a été une révélation pour Johnny Hallyday et l''a poussé à devenir rockeur ?', '["Chuck Berry", "Little Richard", "Elvis Presley", "Buddy Holly"]'::jsonb, '["Chuck Berry", "Little Richard", "Elvis Presley", "Buddy Holly"]'::jsonb, 2, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a86c417486ba780c', 'In the late 1950s, which Parisian venue became the iconic meeting place for young French rockers like Johnny Hallyday?', 'À la fin des années 1950, quel lieu parisien est devenu le rendez-vous incontournable des jeunes rockeurs comme Johnny Hallyday ?', '["Bus Palladium", "Olympia", "Bataclan", "Golf-Drouot"]'::jsonb, '["Bus Palladium", "Olympia", "Bataclan", "Golf-Drouot"]'::jsonb, 3, 'Music', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a5f9f023381a0e68', 'Which iconic song is famously associated with Édith Piaf?', 'Quelle chanson emblématique est associée à Édith Piaf ?', '["Ne me quitte pas", "La Vie en rose", "Comme d''habitude", "La Bohème"]'::jsonb, '["Ne me quitte pas", "La Vie en rose", "Comme d''habitude", "La Bohème"]'::jsonb, 1, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-ccebe1f69c24dc6c', 'Which of these artists was mentored by Édith Piaf?', 'Lequel de ces artistes a été lancé par Édith Piaf ?', '["Johnny Hallyday", "Claude François", "Serge Gainsbourg", "Charles Aznavour"]'::jsonb, '["Johnny Hallyday", "Claude François", "Serge Gainsbourg", "Charles Aznavour"]'::jsonb, 3, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-f573d3d23a01c0ba', 'What was the approximate height of Édith Piaf?', 'Quelle était la taille d''Édith Piaf ?', '["1,55 m", "1,62 m", "1,38 m", "1,47 m"]'::jsonb, '["1,55 m", "1,62 m", "1,38 m", "1,47 m"]'::jsonb, 3, 'Music', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d70b1dc4faf81872', 'Édith Piaf was born in the streets of Paris, not in a hospital.', 'Édith Piaf est née dans la rue, et non dans un hôpital.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-db34783b70dd24e6', 'Which historical figure served as the inspiration for Edith Piaf''s first name?', 'En hommage à quelle célèbre infirmière et résistante le prénom d''Édith Piaf a-t-il été choisi ?', '["Edith Sitwell", "Edith Cavell", "Edith Stein", "Edith Wilson"]'::jsonb, '["Edith Sitwell", "Edith Cavell", "Edith Stein", "Edith Wilson"]'::jsonb, 1, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-37defb9f3bbd5b86', 'Edith Piaf spent part of her childhood in a brothel run by her paternal grandmother.', 'Édith Piaf a passé une partie de son enfance dans une maison close tenue par sa grand-mère paternelle.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-cced469c6f0903bd', 'To which saint did Edith Piaf remain devoted throughout her life after a childhood recovery from blindness?', 'À quelle sainte Édith Piaf est-elle restée dévouée toute sa vie après sa guérison miraculeuse de la vue ?', '["Thérèse of Lisieux", "Bernadette Soubirous", "Joan of Arc", "Catherine Labouré"]'::jsonb, '["Thérèse de Lisieux", "Bernadette Soubirous", "Jeanne d''Arc", "Catherine Labouré"]'::jsonb, 0, 'Music', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b273940bde8700f8', 'How did Edith Piaf begin her musical career at a very young age?', 'Comment Édith Piaf a-t-elle commencé sa carrière musicale alors qu''elle n''était qu''une enfant ?', '["Dancing in a circus", "Singing in the street", "Playing the piano", "Performing in a theater"]'::jsonb, '["En dansant dans un cirque", "En chantant dans la rue", "En jouant du piano", "En jouant au théâtre"]'::jsonb, 1, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-046b2e25d1b8664a', 'Serge Gainsbourg created an alter ego named Gainsbarre in the 1980s.', 'Serge Gainsbourg s''est inventé un alter ego appelé Gainsbarre dans les années 80.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9d3dbadfabaa2508', 'Which artist was Serge Gainsbourg''s primary muse and mother of his daughter Charlotte?', 'Quelle artiste fut la principale muse de Serge Gainsbourg et la mère de sa fille Charlotte ?', '["Françoise Hardy", "Jane Birkin", "Brigitte Bardot", "France Gall"]'::jsonb, '["Françoise Hardy", "Jane Birkin", "Brigitte Bardot", "France Gall"]'::jsonb, 1, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a1e12c038df0d9d4', 'Serge Gainsbourg considered songwriting to be a major art form.', 'Serge Gainsbourg considérait la chanson comme un art majeur.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3cceed6f74e6e749', 'What was the real birth name of the artist known as Serge Gainsbourg?', 'Quel était le véritable nom de naissance de l''artiste connu sous le nom de Serge Gainsbourg ?', '["Gainsbourg Julien", "Lucien Vian", "Serge Gainsborough", "Lucien Ginsburg"]'::jsonb, '["Gainsbourg Julien", "Lucien Vian", "Serge Gainsborough", "Lucien Ginsburg"]'::jsonb, 3, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2b6bd0ddd779218f', 'Before his musical career, which artistic discipline did Serge Gainsbourg study and practice?', 'Avant de se lancer dans la musique, quelle discipline artistique Serge Gainsbourg a-t-il étudiée et pratiquée ?', '["Sculpture", "Painting", "Photography", "Architecture"]'::jsonb, '["La sculpture", "La peinture", "La photographie", "L''architecture"]'::jsonb, 1, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-0adf5174b08cdcbc', 'What is the nationality of the singer Jacques Brel?', 'Quelle est la nationalité du chanteur Jacques Brel ?', '["Canadian", "Belgian", "French", "Swiss"]'::jsonb, '["Canadien", "Belge", "Français", "Suisse"]'::jsonb, 1, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b993ee375b547ae3', 'Jacques Brel spent the final years of his life in the Marquesas Islands.', 'Jacques Brel a passé les dernières années de sa vie aux îles Marquises.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-45b582cf6f4c34e3', 'In 1966, at the height of his fame, Jacques Brel decided to stop performing live to focus on what?', 'En 1966, au sommet de sa gloire, Jacques Brel arrête la scène pour se consacrer à quelle activité ?', '["Painting", "Politics", "Cinema", "Writing novels"]'::jsonb, '["La peinture", "La politique", "Le cinéma", "L''écriture de romans"]'::jsonb, 2, 'Music', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-8db8c010154de088', 'Which of these iconic songs is famously known as one of Jacques Brel''s greatest masterpieces?', 'Parmi ces titres, lequel est considéré comme l''une des plus grandes chansons de Jacques Brel ?', '["L''Aigle noir", "Mistral gagnant", "La Bohème", "Ne me quitte pas"]'::jsonb, '["L''Aigle noir", "Mistral gagnant", "La Bohème", "Ne me quitte pas"]'::jsonb, 3, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-387b788d6cfd66cb', 'Georges Brassens nicknamed Jacques Brel ''L''abbé Brel'' due to his early religious and scout influences.', 'Georges Brassens a surnommé Jacques Brel « L''abbé Brel » en raison de ses influences catholiques et scoutes.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Music', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-6db1469bb8c05752', 'Which musical movement are the Daft Punk duo famous for representing?', 'Quel courant musical le duo Daft Punk a-t-il largement contribué à populariser ?', '["Electro-funk", "French touch", "New Wave", "Synthpop"]'::jsonb, '["Electro-funk", "French touch", "New Wave", "Synthpop"]'::jsonb, 1, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-51f83dd6b3741fcc', 'Which film inspired the iconic robot helmets and costumes worn by Daft Punk?', 'Quel film a inspiré les célèbres casques et costumes de robots portés par Daft Punk ?', '["Tron", "Star Wars", "Blade Runner", "Phantom of the Paradise"]'::jsonb, '["Tron", "Star Wars", "Blade Runner", "Phantom of the Paradise"]'::jsonb, 3, 'Music', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-21ce6316952b154f', 'Before becoming Daft Punk, what was the name of the rock band formed by Thomas and Guy-Manuel?', 'Avant de devenir Daft Punk, quel était le nom du groupe de rock formé par Thomas et Guy-Manuel ?', '["Discovery", "Homework", "Darlin''", "Phoenix"]'::jsonb, '["Discovery", "Homework", "Darlin''", "Phoenix"]'::jsonb, 2, 'Music', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a0d8a9a7b6260768', 'Daft Punk officially announced their split in 2021 through a video titled Epilogue.', 'Le groupe Daft Punk a officiellement annoncé sa séparation en 2021 via une vidéo intitulée Epilogue.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-4f7556639e6e79dc', 'Which duo is behind hits like ''Harder, Better, Faster, Stronger'' and ''Digital Love''?', 'Quel duo est derrière les tubes ''Harder, Better, Faster, Stronger'' et ''Digital Love'' ?', '["Daft Punk", "Air", "Justice", "Cassius"]'::jsonb, '["Daft Punk", "Air", "Justice", "Cassius"]'::jsonb, 0, 'Music', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-f4a575ded1a93c55', 'The animated film ''Interstella 5555'' features the soundtrack of which Daft Punk album?', 'Le film d''animation ''Interstella 5555'' reprend la bande originale de quel album des Daft Punk ?', '["Homework", "Human After All", "Discovery", "Random Access Memories"]'::jsonb, '["Homework", "Human After All", "Discovery", "Random Access Memories"]'::jsonb, 2, 'Music', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3ba57e9f45b52b41', 'During their famous 2006-2007 tour, Daft Punk performed inside a pyramid.', 'Lors de leur célèbre tournée 2006-2007, les Daft Punk se produisaient à l''intérieur d''une pyramide.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Music', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b6b8c8c842e94c69', 'The Daft Punk track ''Robot Rock'' is an original composition.', 'Le titre ''Robot Rock'' des Daft Punk est une composition originale.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'Music', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-32676b888bb716cf', 'Which song made Stromae famous in 2009?', 'Quelle chanson a rendu Stromae célèbre en 2009 ?', '["Santé", "Alors on danse", "Papaoutai", "Formidable"]'::jsonb, '["Santé", "Alors on danse", "Papaoutai", "Formidable"]'::jsonb, 1, 'Music', 'easy', CURRENT_TIMESTAMP),
